package cli

import (
	"strings"
	"testing"
)

func TestBuildApprovalRequestRequiresMessageForRequestChanges(t *testing.T) {
	t.Parallel()
	if _, err := buildApprovalRequest("REQUEST_CHANGES", "  "); err == nil {
